     "text": "روى الشيخان عن أنس بن مالك رضي الله عنه أن ثلاثة رهط جاؤوا إلى بيوت أزواج النبي ﷺ يسألون عن عبادته، فلما أُخبروا كأنهم تقالّوها، فقال أحدهم: أما أنا فأصلي الليل أبدًا، وقال آخر: أنا أصوم الدهر ولا أفطر، وقال آخر: أنا أعتزل النساء فلا أتزوج أبدًا. فجاء رسول الله ﷺ فقال: «أنتم الذين قلتم كذا وكذا؟ أما والله إني لأخشاكم لله وأتقاكم له، لكني أصوم وأفطر، وأصلي وأرقد، وأتزوج النساء، **فمن رغب عن سنتي فليس مني**».\nإنه **منهج واقعي وسطي متوازن** ينقل الفرد إلى أعلى مراتب الإيمان، منهج كامل متكامل لا يحتاج إلى زيادة."
