      "Example: a₁ = 5, r = 5, n = 8 → a₈ = 5(5)⁷ = 5(78,125) = 390,625.",
      "Keep negative r in brackets: −3(−2)ⁿ⁻¹, not −3 · −2ⁿ⁻¹."
