      "answer": "(a) −26,240 = a₁(1 − (−3)⁸)/(1 − (−3)) = a₁(1 − 6561)/4 = −1640a₁ → a₁ = 16.\n(b) a₈ = 16(−3)⁷ = 16(−2187) = −34,992.\n(c) (16 − (−34,992)(−3))/(1 + 3) = (16 − 104,976)/4 = −104,960/4 = −26,240 ✓",
